// Deterministic, browser-independent rules core. No network calls or hidden AI bonuses.
export let HEROES=[];
export const setHeroes=h=>{HEROES=h};
export const hero=id=>HEROES.find(h=>h.id===id);
export const clone=x=>JSON.parse(JSON.stringify(x));
const clamp=(n,a,b)=>Math.min(b,Math.max(a,n));
export function random(s){let x=s.seed|0;x^=x<<13;x^=x>>>17;x^=x<<5;s.seed=x>>>0;return s.seed/4294967296}
export const die=s=>1+Math.floor(random(s)*6);
